<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessageBox } from 'element-plus'
import { api, errorText } from '../api'
import { useAuth } from '../auth'
import { type Row, type ParameterSnapshot, copySnapshot, snapshotPayload } from '../experiments/model'
const props=defineProps<{modelValue:ParameterSnapshot;disabled?:boolean;readonly?:boolean}>()
const emit=defineEmits<{ 'update:modelValue':[ParameterSnapshot] }>()
const auth=useAuth(),templates=ref<Row[]>([]),selected=ref<number|null>(null),templateName=ref(''),busy=ref(false),error=ref('')
function change(edit:(copy:ParameterSnapshot)=>void){const copy=copySnapshot(props.modelValue);edit(copy);emit('update:modelValue',copy)}
async function load(){busy.value=true;error.value='';try{let page=1;const all:Row[]=[];while(true){const r=await api<Row[]>('/step-parameter-templates',{query:{page,size:200}});all.push(...r.data);if(!r.meta?.has_next)break;page++}templates.value=all}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function apply(){const t=templates.value.find(t=>t.template_id===selected.value);if(t){emit('update:modelValue',copySnapshot(t.definition));templateName.value=t.template_name}}
async function saveTemplate(update=false){if(busy.value)return;error.value='';try{const name=templateName.value.trim();if(!name||name.length>128)throw new Error('请填写模板名称（1–128 个字符）');const definition=snapshotPayload(props.modelValue);const t=templates.value.find(t=>t.template_id===selected.value);if(update&&!t)return
if(update){try{await ElMessageBox.confirm('更新模板仅影响以后应用的副本，已有步骤快照保持原值。','更新模板',{confirmButtonText:'更新模板',cancelButtonText:'取消'})}catch{return}}
busy.value=true;const r=await api<Row>(update?`/step-parameter-templates/${t!.template_id}`:'/step-parameter-templates',{method:update?'PATCH':'POST',body:{template_name:name,definition,...(update?{expected_row_version:t!.row_version}:{})}});await load();selected.value=r.data.template_id}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function remove(){const t=templates.value.find(t=>t.template_id===selected.value);if(!t||busy.value)return;try{await ElMessageBox.confirm('删除后已有步骤快照仍保留。','删除模板',{type:'warning',confirmButtonText:'删除',cancelButtonText:'取消'})}catch{return}busy.value=true;try{await api(`/step-parameter-templates/${t.template_id}`,{method:'DELETE',query:{expected_row_version:t.row_version}});selected.value=null;await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
const canManage=()=>{const t=templates.value.find(t=>t.template_id===selected.value);return !!t&&auth.canWrite&&(auth.isAdmin||t.owner_user_id===auth.user?.user_id)}
onMounted(()=>{if(!props.readonly)void load()})
</script>
<template><section class="parameter-editor" data-testid="parameter-groups-editor">
<template v-if="!readonly"><div class="template-tools"><el-select v-model="selected" filterable clearable placeholder="选择已保存的步骤类型 / 模板" :disabled="disabled||busy"><el-option v-for="t in templates" :key="t.template_id" :value="t.template_id" :label="t.template_name" /></el-select><el-button :disabled="disabled||busy||!selected" @click="apply">应用副本</el-button><el-button :disabled="busy" @click="load">刷新模板</el-button></div><p class="field-hint">模板作为独立副本应用到当前步骤；可修改名称、单位与字段。保存步骤后，模板更新不会改变历史。</p><el-alert v-if="error" :title="error" type="error" :closable="false" />
<div class="template-tools" v-if="auth.canWrite"><el-input v-model="templateName" maxlength="128" placeholder="可复用类型 / 模板名称" :disabled="disabled||busy" /><el-button :disabled="disabled||busy" @click="saveTemplate()">另存为模板</el-button><el-button v-if="canManage()" :disabled="disabled||busy" @click="saveTemplate(true)">更新所选模板</el-button><el-button v-if="canManage()" type="danger" link :disabled="disabled||busy" @click="remove">删除模板</el-button></div>
</template>
<div class="temperature"><el-form-item label="步骤类型" required><el-input v-if="!readonly" :model-value="modelValue.step_type" maxlength="128" :disabled="disabled" @update:model-value="(v:string)=>change(c=>c.step_type=String(v))" /><strong v-else>{{ modelValue.step_type }}</strong></el-form-item><el-form-item label="独立温度"><div class="value-unit"><template v-if="!readonly"><el-input :model-value="modelValue.temperature.value" placeholder="未知（NULL）" :disabled="disabled" @update:model-value="(v:string)=>change(c=>c.temperature.value=String(v))" /><el-input :model-value="modelValue.temperature.unit" placeholder="单位" maxlength="32" :disabled="disabled" @update:model-value="(v:string)=>change(c=>c.temperature.unit=String(v))" /></template><span v-else>{{ modelValue.temperature.value??'未知（NULL）' }} {{ modelValue.temperature.unit }}</span></div></el-form-item></div>
<article v-for="(group,gi) in modelValue.groups" :key="gi" class="parameter-group"><div class="group-heading"><el-input v-if="!readonly" :model-value="group.name" aria-label="参数组名称" maxlength="128" :disabled="disabled" @update:model-value="(v:string)=>change(c=>c.groups[gi]!.name=String(v))" /><strong v-else>{{ group.name }}</strong><el-button v-if="!readonly" link type="danger" :disabled="disabled" @click="change(c=>c.groups.splice(gi,1))">删除组</el-button></div><div v-for="(field,fi) in group.fields" :key="fi" class="parameter-row"><template v-if="!readonly"><el-input :model-value="field.name" aria-label="字段名称" placeholder="字段名称" maxlength="128" :disabled="disabled" @update:model-value="(v:string)=>change(c=>c.groups[gi]!.fields[fi]!.name=String(v))" /><el-input :model-value="field.value" aria-label="参数值" placeholder="值（可空）" maxlength="2000" :disabled="disabled" @update:model-value="(v:string)=>change(c=>c.groups[gi]!.fields[fi]!.value=String(v))" /><el-input :model-value="field.unit" aria-label="参数单位" placeholder="单位（可空）" maxlength="32" :disabled="disabled" @update:model-value="(v:string)=>change(c=>c.groups[gi]!.fields[fi]!.unit=String(v))" /><el-button link type="danger" :disabled="disabled" @click="change(c=>c.groups[gi]!.fields.splice(fi,1))">删除</el-button></template><template v-else><span>{{ field.name }}</span><span>{{ field.value??'未知（NULL）' }}</span><span>{{ field.unit }}</span></template></div><el-button v-if="!readonly" link type="primary" :disabled="disabled||group.fields.length>=64" @click="change(c=>c.groups[gi]!.fields.push({name:'',value:null,unit:null}))">添加字段</el-button></article><el-button v-if="!readonly" :disabled="disabled||modelValue.groups.length>=32" @click="change(c=>c.groups.push({name:'',fields:[]}))">添加参数组</el-button>
</section></template>
<style scoped>
.parameter-editor{display:grid;gap:14px}.template-tools{display:flex;flex-wrap:wrap;gap:8px}.template-tools>.el-select,.template-tools>.el-input{flex:1;min-width:200px}.temperature{display:grid;grid-template-columns:1fr 1fr;gap:16px}.value-unit{display:flex;gap:8px}.value-unit>.el-input:last-child{max-width:100px}.parameter-group{border:1px solid var(--line,#dce6e4);border-radius:8px;padding:14px;background:var(--soft,#f5f8f7)}.group-heading{display:flex;align-items:center;gap:12px;margin-bottom:10px}.group-heading>.el-input{max-width:320px}.parameter-row{display:grid;grid-template-columns:1.2fr 1fr .6fr auto;gap:8px;align-items:center;margin:8px 0}@media(max-width:620px){.temperature{grid-template-columns:1fr}.parameter-row{grid-template-columns:1fr 1fr}.parameter-group{padding:10px}}
</style>
